{
  "status": "SUPPORTED",
  "task_summary": "Find compatible parts and a tool in storage, fasten parts at a specific location, and leave the tool on the table.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "component",
        "entity_kind": "OBJECT",
        "function": "Physical part required for the assembly or fastening process.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "block",
          "screw",
          "nut",
          "part"
        ],
        "required_properties": [
          "compatible_with_fastening",
          "fit_to_location"
        ]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "Implement used to perform the fastening action.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "hammer",
          "implement"
        ],
        "required_properties": [
          "suitable_for_fastening"
        ]
      },
      {
        "id": "workpiece_location",
        "entity_kind": "REGION",
        "function": "Specific area on the workbench where the fastening occurs.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "table_surface",
          "tray",
          "mounting_point"
        ],
        "required_properties": [
          "accepts_fastening"
        ]
      },
      {
        "id": "storage_unit",
        "entity_kind": "OBJECT",
        "function": "Enclosed structure containing hidden components or tools.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "drawer",
          "cabinet",
          "box",
          "container"
        ],
        "required_properties": [
          "openable",
          "contains_items"
        ]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "Surface where the task is performed and where equipment must be left.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "table",
          "bench",
          "surface"
        ],
        "required_properties": [
          "supports_objects",
          "flat_surface"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_1",
        "relation": "component fits workpiece_location",
        "participant_roles": [
          "component",
          "workpiece_location"
        ]
      ,
      "required": true
      },
      {
        "id": "relation_2",
        "relation": "tool operates on component",
        "participant_roles": [
          "tool",
          "component"
        ]
      ,
      "required": true
      },
      {
        "id": "relation_3",
        "relation": "storage_unit contains tool",
        "participant_roles": [
          "storage_unit",
          "tool"
        ]
      ,
      "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_1",
        "operation": "search",
        "participant_roles": [
          "storage_unit"
        ,
        "required_count"
        ]
        	,
        "operation_count": 1
      },
      {
        "id": "op_2",
        "operation": "fasten",
        "participant_roles": [
          "component",
          "tool",
          "workpiece_location"
        ]
        ,
        "operation_count": 1
      },
      {
        "id": "op_3",
        "operation": "place",
        "participant_roles": [
          "tool",
          "workbench"
        ]
        ,
        "operation_count": 1
      }
    ]
  },
